-- index pipeline_runs_one_active), so pressing "Run now" twice starts one run.
--
-- Parameters, with the example values used to render this file:
--   $1 = "manual"
--   $2 = "0199c8a0-0000-7000-8000-00000000000a"
--
-- Generated by `pnpm db:queries` from lib/db/queries/pipeline.ts. Do not edit by hand.

insert into "pipeline_runs" ("id", "trigger", "requested_by", "status", "started_at", "finished_at", "items_seen", "items_new", "candidates_new", "outlet_results", "error", "created_at", "updated_at")
values (default, $1, $2, default, default, default, default, default, default, default, default, default, default)
on conflict do nothing
returning "id";
